import{c as a,Q as s,j as t,m as i}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Build a Self-Updating LLM Knowledge Base","description":"","frontmatter":{"url":"https://x.com/BHolmesDev/status/2074499909785461170","title":"Build a Self-Updating LLM Knowledge Base","author":"Ben Holmes","archived":"2026-07-12T00:00:00.000Z","handle":"@BHolmesDev","published":"2026-07-07T00:00:00.000Z","stats":"363 likes · 43 retweets · 857 bookmarks · 28765 views","tags":["llm-wiki","second-brain","enrich-note-skill","idempotency","karpathy","scheduled-automation","cloud-sandbox"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-07-@BHolmesDev-461170.md","filePath":"research/tweets/2026-07-07-@BHolmesDev-461170.md","lastUpdated":1785909234000}'),n={name:"research/tweets/2026-07-07-@BHolmesDev-461170.md"};function o(l,e,r,d,h,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="build-a-self-updating-llm-knowledge-base-—-bholmesdev" tabindex="-1">Build a Self-Updating LLM Knowledge Base — @BHolmesDev <a class="header-anchor" href="#build-a-self-updating-llm-knowledge-base-—-bholmesdev" aria-label="Permalink to &quot;Build a Self-Updating LLM Knowledge Base — @BHolmesDev&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/BHolmesDev/status/2074499909785461170" target="_blank" rel="noreferrer">https://x.com/BHolmesDev/status/2074499909785461170</a><strong>作者</strong>：Ben Holmes（@BHolmesDev） <strong>發布日期</strong>：2026-07-07 <strong>收錄日期</strong>：2026-07-12 <strong>類型</strong>：Twitter Article <strong>統計</strong>：363 likes · 43 retweets · 857 bookmarks · 28765 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>You may have seen Andrej Karpathy talk about &quot;LLM Wikis.&quot; They turn your unorganized thoughts into easy-to-navigate notes, wikis, or visualizations. It&#39;s an incredibly powerful tool for researchers, software developers, scattered notetakers... basically everyone. Here&#39;s the system to have agents organize your second brain automatically:</p><ol><li>Start taking notes as markdown</li><li>Add an /enrich-note skill that instructs agents to add tags, sources, and backlinks</li><li>Add a wiki skill that compounds notes into a persistent knowledge base</li><li>Create automations that run these skills on a schedule</li><li>Add visualizations built live from your notes I published a YouTube walkthrough of the setup as well!</li></ol><h2 id="step-1-one-directory-of-raw-markdown" tabindex="-1">Step 1: one directory of raw markdown <a class="header-anchor" href="#step-1-one-directory-of-raw-markdown" aria-label="Permalink to &quot;Step 1: one directory of raw markdown&quot;">​</a></h2><p>We&#39;re going to take our notes as Markdown to make them easily accessible to agents. You can use Obsidian for this, or if you want a friendlier app that feels more like Apple Notes, I built one: Hubble.md. Following Andrej Karpathy&#39;s recommendation, we&#39;ll put all of our handwritten (or voice-transcribed) notes in a raw/ directory. These files are raw, unfiltered thoughts, for our agents to work with.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>raw/</span></span>
<span class="line"><span>├── rick-rubin-s-philosophy-of-simplicity.md</span></span>
<span class="line"><span>├── nvidia-blackwell-architecture.md</span></span>
<span class="line"><span>├── insights-from-sell-like-steve-jobs.md</span></span>
<span class="line"><span>└── acquired-pod-ferrari.md</span></span></code></pre></div><p>Here&#39;s a sample I rambled out using a voice transcription tool after listening to Acquired&#39;s Ferrari episode:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Ferrari (Acquired)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">It was super interesting how they described Ferrari as a brand, where</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">it&#39;s both a combination of a luxury brand, like a Hermes or a Gucci,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">but also a sports team, which explains why they can put their logo on</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">everything down to an Acer laptop...</span></span></code></pre></div><p>Note there&#39;s no metadata and no backlinks. Honestly, you don&#39;t even need the header. The agent will handle those details for you.</p><h2 id="step-2-the-enrich-note-skill" tabindex="-1">Step 2: the /enrich-note skill <a class="header-anchor" href="#step-2-the-enrich-note-skill" aria-label="Permalink to &quot;Step 2: the /enrich-note skill&quot;">​</a></h2><p>Let&#39;s have agents enrich these notes with details for easy retrieval. I wrote the /enrich-note skill to do this. You can grab it (and every other skill in this post) with one command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npx skills add bholmesdev/llm-knowledge-base-skills</span></span></code></pre></div><p>The skill does three things:</p><ol><li>Tags: The skill maintains a shared tag registry as a tags.md file listing every tag with a one-line description. I suggest tags relating to the medium of the source (blog, podcast, video) and others relating to topics / areas of interest (ai-hardware, business, rust). The agent is also told to reuse existing tags and be reluctant to coin new ones. Otherwise, I&#39;ve found agents invent tags too liberally.</li><li>Sources: If the note came from somewhere (a podcast, a book, a video) the agent does some web research to find the source URL and records it in frontmatter.</li><li>Related notes: The agent greps the rest of the vault for genuinely related notes and adds them as wikilinks in a ## Related section. This can be an expensive operation, but no more expensive than asking an agent to complete a coding task in a small-to-medium-sized codebase. I personally have hundreds of notes. If you test this on a larger corpus let me know what you&#39;ve learned or optimizations you&#39;ve found.</li></ol><p>After a pass, that Acquired podcast note on Ferrari looks like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>tags: [podcast, business, branding]</span></span>
<span class="line"><span>source: &quot;Acquired podcast — \\&quot;Ferrari\\&quot;&quot;</span></span>
<span class="line"><span>url: &quot;https://www.acquired.fm/episodes/ferrari&quot;</span></span>
<span class="line"><span>enrichedAt: &quot;2026-06-27T23:40:26Z&quot;</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span># Ferrari (Acquired)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Related</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- [[raw/walt-disney.md|Walt Disney on Acquired]]</span></span></code></pre></div><p>Note the enrichedAt stamp. That&#39;s how an automation knows which notes have been enriched in the past. Idempotency matters when we start running this skill on a schedule.</p><h2 id="step-3-the-wiki-skill" tabindex="-1">Step 3: the wiki skill <a class="header-anchor" href="#step-3-the-wiki-skill" aria-label="Permalink to &quot;Step 3: the wiki skill&quot;">​</a></h2><p>Enriched notes are searchable, but they&#39;re still fragments. The next layer up is a wiki: a persistent, interlinked knowledge base that an agent builds from your notes. This comes directly from Karpathy&#39;s llm-wiki gist, which I&#39;d recommend reading in full. The core idea: have an agent generate a frontpage around an area of interest (in my case, coding agent tips or religious studies) that is easy-to-navigate. This is useful for you since it creates an easy-to-scan index of people, places, and things. But it&#39;s also useful for agents to navigate whenever you ask questions relating to your notes. Instead of RAG-style retrieval where the LLM rediscovers your knowledge from scratch on every question, the agent maintains a compounding artifact: entity pages, topic syntheses, an index, a log. As Andrej puts it: &quot;the LLM is the programmer; the wiki is the codebase.&quot; To get started, paste the gist into your agent and add a sentence about what you want. Something like:</p><blockquote><p>Read this: <a href="https://gist.github.com/karpathy/442a6bf555914893e9891c11519de94f" target="_blank" rel="noreferrer">https://gist.github.com/karpathy/442a6bf555914893e9891c11519de94f</a>. Set up a wiki in wikis/latest-ai/ that tracks coding agent tips from my notes - model prompting, orchestration patterns, useful agent skills, etc. Seed it from anything relevant in raw/. The agent scaffolds the directory, writes its own AGENTS.md schema with wiki maintenance instructions, and ingests your existing notes. From then on, I wrote a skill to &quot;refresh&quot; that wiki over time: /refresh-wiki. This looks for new or changed notes in raw/, ingests the relevant ones into each wiki, updates entity and concept pages, and runs a lint pass for contradictions, orphan pages, and stale claims. Here&#39;s a trimmed view of the index.md for my &quot;Latest in AI&quot; wiki. This was built from podcast and video notes I&#39;ve taken over the past few months, and every entry links to a full page the agent writes and maintains:</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Index — Latest in AI wiki</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Sources (20)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- [[nvidia-blackwell|NVIDIA Blackwell Architecture]] — Gavin Baker note on GB200/B200, token efficiency, and the shift from raw intelligence to usefulness.</span></span>
<span class="line"><span>- [[ralph-loops|Ralph Loops in Claude Code]] — Theo note on wrapping Claude Code in external scripts for REPL-like loops.</span></span>
<span class="line"><span>- [[ai-music-production|The Impact of AI on Music Production]] — Adam Neely/Suno note about curation vs. creation.</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Concepts (16)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- [[agent-loops|Agent Loops]]</span></span>
<span class="line"><span>- [[software-factories|Software Factories]]</span></span>
<span class="line"><span>- [[inference-economics|Inference Economics]]</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## People (8)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- [[boris-cherny|Boris Cherny]] — Creator of Claude Code; cited as saying his work has shifted from prompting Claude to writing loops.</span></span>
<span class="line"><span>- [[andrew-wilkinson|Andrew Wilkinson]] — Quoted on Claude Code helping him move at the speed of his ADHD.</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>I also keep a wiki for my Bible study through Lee Strobel&#39;s The Case for Christ. The book is a long series of expert interviews, so the agent built out a &quot;people&quot; index with a page for every interviewee: who they are, and what they argued. I&#39;ve found this super helpful for revisiting arguments weeks later, since names tend to blend together for me without a glossary:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## People (18)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">lee-strobel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] — author/journalist; the investigator and convert.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">craig-blomberg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] — New Testament scholar; gospel reliability &amp; early dating.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">alexander-metherell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] — physician; the medical reality of the crucifixion.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">william-lane-craig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] — apologist; the empty tomb &amp; the God hypothesis.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">gary-collins</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] — psychologist; the mental health of Jesus.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span></code></pre></div><h2 id="step-4-automations" tabindex="-1">Step 4: automations <a class="header-anchor" href="#step-4-automations" aria-label="Permalink to &quot;Step 4: automations&quot;">​</a></h2><p>These skills are useful, but I&#39;d rather not re-run these every time I go to browse my notes or ask an agent a question. Both skills have loop variants designed to run on a schedule:</p><ul><li>/enrich-notes-loop wraps /enrich-note and walks every note you&#39;ve taken recently, using enrichedAt to ignore previously crawled entries.</li><li>/refresh-wiki walks through your wikis/ directory and updates every wiki it finds. (You&#39;ll want your wikis in a wikis/ directory. You can tweak all of this to taste.) There are two options I&#39;d suggest trying: local automations to get started, and cloud automations to make the workflow durable.</li></ul><p>Local Automations with Codex You can schedule these in a few ways. One is a local automation that runs on your computer, waking up to organize the notes folder on a cron. The Codex app offers this from the Scheduled tab: [圖 1] From here, click &quot;Create with chat,&quot; select the directory where your notes live, and specify the skill to run. I suggest scheduling to run daily on an overnight schedule. I also suggest a lower reasoning level for /enrich-notes-loop since it&#39;s a less ambiguous skill. For wiki generation, a higher reasoning level may let the model be more thoughtful / creative. Tweak to taste. [圖 2]</p><p>Cloud Automations While local automations are the easiest way to get started, they do have a pretty obvious drawback: your computer will need to be awake and running for the task to execute. Codex in particular did ensure that scheduled jobs run even when a laptop lid is closed. Still, I noticed when I went out of town for a few days that my automations stopped running since I forgot to plug in my laptop... 🤦‍♂️ Given that, I&#39;d suggest trying cloud runners. Here&#39;s a setup guide with the tools I use:</p><ul><li>oz.dev to create a cloud sandbox connected to open-weight models</li><li>Obsidian Sync to sync markdown notes to the cloud</li><li>Obsidian&#39;s headless CLI to access those notes programmatically from a cloud sandbox Oz is Warp&#39;s cloud hosting platform for agents. It charges mostly at token cost, yes. But open-weight models like Kimi k2.6 are highly token efficient (3-4x fewer tokens than Claude&#39;s models) and high quality. Here&#39;s the flow each scheduled run follows:</li></ul><ol><li>The agent uses the Obsidian CLI to pull the vault down into the cloud sandbox</li><li>It runs /enrich-notes-loop or /refresh-wiki</li><li>It pushes the results back up, which sync down to your machine I wrote two more skills to run these with the necessary cloud sandbox setup: /enrich-notes-loop-cloud and /refresh-wiki-cloud. They&#39;re thin wrappers that sync the vault down, run the base skill, and sync back up. The environment and schedule setup is a handful of oz CLI commands, so I encoded that as a skill too: /setup-oz-automations. First, make an account: go to oz.dev and click &quot;start an agent.&quot; That takes you through login, where you can create an account. Then install the skills (if you haven&#39;t already) and hand the rest to your agent:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npx skills add bholmesdev/llm-knowledge-base-skills</span></span></code></pre></div><blockquote><p>Run the /setup-oz-automations skill</p></blockquote><p>The skill checks for Warp&#39;s Oz platform skill and walks through the remaining cloud setup steps.</p><h2 id="step-5-visualizations" tabindex="-1">Step 5: visualizations <a class="header-anchor" href="#step-5-visualizations" aria-label="Permalink to &quot;Step 5: visualizations&quot;">​</a></h2><p>build interactive visualizations on top of them using HTML. I&#39;ve built a few examples you can plug into your setup, assuming you have your notes in a raw/ directory: Notes burndown: a GitHub-style activity graph of your note-taking over time. I&#39;m using it to build a consistent journalling habit. [圖 3] Thought constellation: display notes as a graph clustered by your most-used tags (a payoff of /enrich-note). It helped me find my most referenced notes for a second read, and figure out gaps where I should focus next (clearly I need to read more...) [圖 4] You can build these as one-off visualizations updated on a schedule, similar to our /enrich-note and wiki examples. But if you want these to live-update by reading files from disk, you can view these visualizations within Hubble.md. This is the markdown notes app I mentioned earlier. This lets you view HTML apps alongside your notes, and injects runtime APIs to read files in the current directory to build visuals that update programmatically.</p><h2 id="go-write-things-down" tabindex="-1">Go write things down! <a class="header-anchor" href="#go-write-things-down" aria-label="Permalink to &quot;Go write things down!&quot;">​</a></h2><p>All the skills and visualizations are in this GitHub repo. To start, just ask your agent to convert your existing notes into Markdown (Apple Notes, Notion, Granola, etc. all support this). Then try some of the skills I shared here to see if they help you. Build a wiki around your next research project, side hobby, or agentic coding session. Invent a new visualization and share it here. I&#39;m curious what you come up with! Also, give both oz.dev and Hubble.md a try 😃</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：raw notes → <code>/enrich-note</code>（標籤+來源+backlink）→ wiki skill（Karpathy llm-wiki）→ 排程自動化 → 可視化，五步驟自建個人知識庫。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li>五步驟系統：① 原始筆記存成 markdown 放 <code>raw/</code> ② <code>/enrich-note</code> skill 幫每篇筆記補標籤/來源/相關連結 ③ wiki skill（源自 Karpathy 的 llm-wiki gist）把零散筆記濃縮成持久化、可導覽知識庫 ④ 排程自動化定期跑上述兩個 skill ⑤ 從筆記即時產生視覺化。</li><li><code>/enrich-note</code> 用共享 <code>tags.md</code> 標籤登記表避免 agent 亂造標籤、frontmatter 記錄來源 URL、用 <code>enrichedAt</code> 時戳做 idempotency（排程重跑時跳過已處理筆記）。</li><li>wiki 是「複利型 artifact」而非每次重新從零檢索：entity 頁、主題綜整頁、index、log，Karpathy 原話「LLM 是 programmer，wiki 是 codebase」。</li><li>排程自動化分本地（Codex Scheduled tab，跑 cron）與雲端（oz.dev 雲端沙盒 + Obsidian Sync + headless CLI）兩種，作者實測本地排程會因筆電沒插電而中斷，建議雲端排程確保穩定執行。</li><li>全部 skill（<code>/enrich-note</code>、<code>/refresh-wiki</code>、<code>/enrich-notes-loop</code>、<code>/refresh-wiki-cloud</code>、<code>/setup-oz-automations</code>）皆已發佈為可安裝套件：<code>npx skills add bholmesdev/llm-knowledge-base-skills</code>。</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>GitHub repo：<code>bholmesdev/llm-knowledge-base-skills</code>（含全部 skill 與視覺化範例），另有 YouTube walkthrough。</li><li>Karpathy llm-wiki gist：<code>gist.github.com/karpathy/442a6bf555914893e9891c11519de94f</code>。</li><li>雲端執行模型建議：Kimi k2.6（開源權重模型，token 效率比 Claude 系列高 3-4 倍）。</li><li>兩個實際案例展示：AI/coding agent 主題 wiki（20 sources / 16 concepts / 8 people）與 Bible study wiki（18 people 索引頁）。</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>整套架構（raw notes → enrich → 持久化 wiki → 排程刷新）與本 workspace <code>research/</code> 目錄體系（media-research 歸檔 + README/INDEX 分類索引 + dreaming-consolidator 跨 session 萃取 playbook）幾乎同構，<code>enrichedAt</code> idempotency 手法與本 skill 自身的 Step 2.5 Idempotency 檢查設計思路一致，可直接借鏡標籤登記表（tags.md）做法統一 research/tweets 的 tag 詞彙。</li><li>提供實際可安裝的 GitHub repo 與具體 before/after 範例（原始語音轉錄筆記 → enriched frontmatter），證據品質優於多數同類推文；但「幫大量筆記找 related notes 開銷不小」的成本問題作者僅口頭帶過，未附具體 token/時間成本數字。</li><li>雲端執行部分（oz.dev、Warp 平台、Kimi k2.6）綁定特定第三方服務，若該服務停運或改版，此段落可攜性會下降；核心 skill 邏輯（enrich/wiki/idempotency）本身與雲端平台解耦，泛化性仍高。</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>與現有 research/ 歸檔 + dreaming-consolidator 高度同構，tags.md 登記表可直接借鏡</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>站在 Karpathy llm-wiki 基礎上補強 enrich pipeline + idempotency + 排程雙軌，工程整合紮實</td></tr><tr><td>C. 證據品質 (20%)</td><td>8/10</td><td>附真實 GitHub repo、before/after 範例、實際 wiki index 截取，一手證據充分</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>涵蓋 idempotency、reasoning-level 調校、本地/雲端排程權衡等具體實作細節</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>任何有 markdown 筆記與排程能力的 agent 平台皆可套用，僅雲端段落綁定特定廠商</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.8/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：SKILL <strong>理由</strong>：核心是可安裝、可重現的靜態 skill 系統（enrich-note/wiki/idempotency/排程），與 research-hub、dreaming-consolidator 有直接互補空間，建議評估納入 tags.md 統一標籤機制。</p>`,53)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
